(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["la"] = {"ui":{"skip":"Ad contentum transire","back":"← Ad AI-gile redire","lang.button":"Lingua: {name}","lang.dialog":"Linguam elige","lang.search":"Linguas quaerere","lang.none":"Nulla lingua congruit","lang.notYet":"{name} nondum translata est","theme.aria":"Inter thema lucidum et obscurum mutare","theme.toLight":"Ad thema lucidum mutare","theme.toDark":"Ad thema obscurum mutare","index.title":"AI-gile: turma tua AI ad programmandum, in una tabula","index.description":"AI-gile est tabula kanban pro turmis AI programmantibus. Laborant dum dormis; tibi unus brevis acervus manet rerum decernendarum, temptandarum et accipiendarum.","hero.logoAlt":"Icon tabulae AI-gile","hero.h1.html":"Turma tua AI ad programmandum, in una&nbsp;tabula.","hero.alpha":"🐣 Alpha praevia clausa","hero.alphaTitle":"Rudis et imperfecta: gratias quod temptas!","hero.lede":"Aedificant dum dormis. Expergefactus unum acervum brevem invenis: paucas quaestiones, pauca temptanda, unum alterumve adamantem purpureum. Preme, accipe, ad tuum capulum redi.","dl.windows":"Applicatio Windows","dl.browser":"In navigatro age","dl.soon":"Mox","dl.notify":"🔔 Me certiorem fac cum aperietur","dl.notifySmall":"Alpha vel beta","hero.secondary":"Agile, sed turma numquam capulo stantium conventuum eget. (Conventus tamen habet.)","pitch.h2":"AI-gile tot verbis quot vis","pitch.lede":"Longitudinem elige, ab uno verbo ad CXLIV. Quaeque longitudo propria descriptio est, huic magnitudini scripta. Trahe indicem vel claves sagittarum preme.","pitch.rangeLabel":"Longitudo verborum","pitch.dice":"🎲 alia versio","pitch.words.one":"{n} verbum","pitch.words.other":"{n} verba","pitch.letters.one":"{n} littera","pitch.letters.other":"{n} litterae","pitch.chars.one":"{n} signum","pitch.chars.other":"{n} signa","count.line.html.one":"{n} charta in tabula nunc","count.line.html.other":"{n} chartae in tabula nunc","features.aria":"Quid faciat","f.pile.h":"Unus acervus tibi","f.pile.html":"<b>Tibi</b> omnia tenet quae te exspectant, ex omnibus inceptis: quaestiones, temptanda, opera quae solus homo conficere potest. Ordo tuus indicat quid proximum sit et quamdiu duret.","f.sleep.h":"Turmae quae dormiente te laborant","f.sleep.p":"Quodque inceptum ducem habet et turmam agentium AI. Chartam commenta, et turma expergiscitur, opus facit, et reddit cum gradibus quos homo defessus sequi possit.","f.tester.h":"Probator AI primus inspicit","f.tester.p":"Antequam quicquam ad te perveniat, probator gradus in exemplo applicationis sequitur et ostendit quid viderit, cum imagine ex scaena capta. Percurre ea quae probata sunt et uno ictu accipe.","f.proof.h":"Probationes, non promissa","f.proof.p":"Quaeque traditio ostendit quid mutatum sit: fasciculos, differentias, imagines. Non necesse est omnes applicationes aperire ut scias num perfectum sit.","f.chat.h":"Cum ducibus tuis colloquere","f.chat.p":"Series ut in Discord: una icon pro quoque incepto, adamantes purpurei pro iis quae te requirunt. Duci ideam scribe; is eam in chartas et consilium vertit, cum bullula ✅ Age.","f.tidy.h":"Se ipsa ordinat","f.tidy.p":"Chartae cognatae in unam coeunt, tituli perturbati corriguntur, et signorum inspectio codicem levem servat. Pauciora quae mutes, minus quod cogites.","f.private.h":"Tua, in computatro tuo","f.private.li1":"Tabula in tuo computatro currit et tibi soli respondet.","f.private.li2":"Nuntii privati inter homines ab initio ad finem cryptantur.","f.private.li3":"Nulli rationes, nulli indagatores, nullae crustulae.","f.lang.h":"In lingua tua","f.lang.p":"Plus quam CXX linguae, a Batava, Cambrica et Iaponica ad piraticam, Yodae et Klingonicam, cum celeri reditu ad Anglicam pro verbis programmatorum.","tl.aria":"Linea temporis a primo colloquio ad iter futurum","tl.h2":"A primo colloquio ad id quod sequitur","tl.lede":"Verae dies et horae, in tua zona temporis. Post hodiernum diem consilium est, sine diebus promissis.","tl.today":"Hodie","tl.planned":"destinatum","tl.cards.one":"{n} charta","tl.cards.other":"{n} chartae","join.h2":"Adiunge te","join.lede":"AI-gile ab homine parvo et magno numero agentium patientium aedificatur. Nunc privata est, in alpha clausa cum amicis. Visne temptare cum aperietur?","join.btn":"Studium profiteri","join.small":"Epistulam tibi mittemus, nihil aliud","footer.tag":"AI-gile. Nulli indagatores, nullae crustulae, nullus capulus stantium.","footer.licence":"Licentia negotiorum","footer.status":"Status","form.sending":"Mittitur…","form.failed":"Non successit: postea iterum conare.","form.offline":"AI-gile attingi non potuit: postea iterum conare.","interest.title":"AI-gile: dic mihi cum alpha aperietur","interest.description":"Inscribe epistulam electronicam ut audias cum alpha vel beta clausa AI-gile aperiatur.","interest.h1":"🔔 Dic mihi cum aperietur","interest.lede":"AI-gile in alpha praevia clausa est. Epistulam tuam relinque et semel scribemus, cum locus tibi erit.","interest.email":"Epistula tua electronica","interest.which":"Quae probatio?","interest.alpha":"Alpha clausa: praevia, rudis, multae mutationes","interest.beta":"Beta: stabilior, posterius","interest.both":"Utralibet, quaecumque prior erit","interest.submit":"Me in indicem pone","interest.thanks":"Gratias! In indice es.","interest.kept":"Sola epistula tua et probatio electa servantur, huic indici soli. Nullae litterae periodicae, nulli indagatores.","licence.title":"AI-gile: licentia negotiorum","licence.description":"AI-gile in negotio tuo uteris? Licentiam negotiorum gratuitam pete.","licence.h1":"📜 Licentia negotiorum","licence.lede":"AI-gile in opere uteris? Dic nobis quis sis et quid agas. Si aliquid boni facit, licentia gratuita est.","licence.company":"Societas","licence.website":"Situs interretialis","licence.what":"Quid agas","licence.how":"Quomodo mundum iuvet","licence.email":"Epistula electronica","licence.submit":"Petere","licence.thanks":"Gratias! Per epistulam respondebimus.","status.title":"Status AI-gile","status.h1":"Status AI-gile","status.quiet":"Omnia quieta","status.checking":"Inspicitur…","status.offline":"Ministerium status nunc attingi non potest (iterum conamur)","status.updated":"renovatum {ago}","status.justNow":"modo","status.min":"ante {n} min.","status.hours":"ante {n} h.","status.days":"ante {n} d.","live.h2":"Specta dum aedificatur, vivum","live.caption":"Omnis charta abscondita est: formam operis vides, non verba.","live.watching.one":"vivum: {n} spectat","live.watching.other":"vivum: {n} spectant","live.offline":"Tabula viva paulum quiescit. Mox revertere.","live.cols":"Backlog|Agenda|In opere|Turma inspicit|Tibi testandum|Turmae|Confecta"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Automata.","Delegatum."]},{"n":2,"texts":["Kanban automatorum.","Agentes ordinati.","Ideae aedificatae."]},{"n":3,"texts":["Kanban pro automatis.","Ideae fiunt functiones.","Kanban agentium gratuitum."]},{"n":5,"texts":["Tabula kanban ab agentibus acta.","Chartas scribis. Agentes aedificant.","Gratuita, localis, probata, paulum ridicula."]},{"n":8,"texts":["Tabula kanban gratuita ubi agentes AI laborant.","Ideam scribe. Agentes aedificant. Tu accipis.","Agile pro uno homine et multis automatis patientibus."]},{"n":13,"texts":["Tabula kanban in computatro tuo, ubi agentes AI chartas suscipiunt et perficiunt.","Ideam scribe. Turma agentium eam aedificat. Probator inspicit. Tu denique approbas.","Sine rationibus, sine indagatoribus: tabula, pauca automata, et tu imperator."]},{"n":21,"texts":["AI-gile est tabula kanban ad laborandum cum agentibus AI programmantibus. Illi chartas suscipiunt; tu eas temptas et accipis.","Quodque inceptum ducem habet et turmam agentium AI. Quamlibet chartam commenta, et turma ad opus se accingit.","Tabula personalis gratuita rerum agendarum, in computatro tuo proprio currens, sine rationibus. Operarii sunt automata patientia. Qui annuit, tu es."]},{"n":34,"texts":["Ideas in tabulam ponis. Turma agentium AI eas in functiones vivas convertit, temptat, et tibi reddit cum gradibus experiendi. Nihil perfectum habetur donec tu dixeris. Omnia in una tabula manent.","AI-gile est tabula kanban domi facta, quam Rich magno agentium auxilio aedificavit, quos nunc ipsa regit. Gratuita est, in computatro tuo currit, et cum amicis communicatur, non venditur.","Finge tabulam kanban consuetam, cum columnis a Backlog ad Done, nisi quod chartas agentes AI suscipiunt. Progressum nuntiant, haerentes interrogant, et semper tuum pollicem sursum exspectant. Omnes columnas uno aspectu vides."]},{"n":55,"texts":["AI-gile est tabula kanban ubi turma ex agentibus AI constat. Quodque inceptum ducem habet qui opus designat, et adiutores qui id aedificant. Cum functio parata est, probator AI eam temptat et imaginem ex scaena capit, deinde in acervum tuum venit. Accipe eam, vel commenta, et iterum elaborabunt.","Initium fuit unius hominis modus plurimas sessiones AI programmantes simul observandi, et in tabulam veram crevit. In tuo computatro currit, rationem non postulat, indagatores non habet. Amicis et curiosis gratuita est. Etiam imperfecta est, ergo asperitates et casus subitos exspecta. Cotidie paulatim crescit, cum amicis qui eam temptant.","Ecce versio sincera. Ideas adhuc tibi habendae sunt, et eventus adhuc tibi inspiciendi. Quod AI-gile facit est omne quod interest: chartas in ordine servat, agentem rectum excitat cum commentaris, ostendit quid mutatum sit, et omnia in uno acervo brevi tibi colligit. Tibi manet pars iucundissima: excogitare et decernere."]},{"n":89,"texts":["AI-gile est tabula kanban gratuita quam in computatro tuo agis. Pro hominibus quodque inceptum turmam agentium AI habet: ducem qui ideas tuas in chartas et consilium vertit, et adiutores qui chartas ordine momenti suscipiunt. Cum aliquid aedificatum est, probator AI gradus probationis sequitur et ostendit quid viderit. Deinde in uno acervo exspectat qui inscribitur Tibi. Accipis, vel commentaris et turma iterum conatur. Nihil ad Done sine te pervenit. Haec omnia in computatro tuo fiunt, sine rationibus et sine indagatoribus.","Quaedam quae fortasse non exspectas. Vigilia nocturna columnam Agenda replet dum dormis, chartas eligens quae responsum tuum non requirunt. Numerator signorum ostendit quantum agentes hodie et hac hebdomada consumpserint, et No Token Mode eos desistere iubet. Amicis scribere potes, et nuntii privati ab initio ad finem cryptantur. Tabula circiter CXX linguis loquitur, inter eas Batava, Flandrica, piratica et Klingonica. Nihil constat, nec quisquam tibi eam vendere conatur. Omnia in computatro tuo localiter funguntur, sine nubibus.","AI-gile est parvum inceptum personale, non societas. Rich plura incepta AI programmantia curare voluit, non omnes applicationes aperiens ut inspiceret, itaque cum agentibus tabulam ad hoc fecit, deinde ea tabula reliquum sui ipsius aedificavit. In alpha praevia clausa est, quod significat eam, fere, paucis amicis fungi. Nulla pagina pretiorum, nullae litterae periodicae, nullum incrementi consilium. Si utilis videtur, rogare potes ut temptes cum paulo apertior erit. Nulla pressio est, tantum tabula quae paulatim melior fit."]},{"n":144,"texts":["AI-gile est tabula kanban pro uno homine et multis agentibus AI. In tuo ipsius computatro currit et omnino gratuita est. Incepta addis, et quodque ducem et parvam turmam accipit. Cum duce colloqueris, quasi in Discord, et ideam describis; dux eam in chartas et consilium vertit, deinde exspectat dum Age premis. Turma chartas ordine momenti pertractat, per simplicem lineam mandatorum ad exempla linguae factam. Antequam quicquam ad te redeat, probator AI gradus in exemplo applicationis sequitur et imaginem ex scaena capta adiungit. Opus perfectum in acervum tuum venit cum fasciculis mutatis et differentiis. Accipis, vel commentarium relinquis, et turma expergiscitur ac iterum conatur. Solus tu chartam ad Done movere potes. Haec omnia in computatro tuo fiunt, sine rationibus, sine indagatoribus, sine crustulis.","Dies cum AI-gile, fere. Vespere paucos commentarios relinquis: hic bulla in loco falso est, ille index ordinandus est, possumusne thema obscurum habere. Cubitum is. Agentes commentarios legunt, mutationes faciunt, eas temptant et tibi reddunt. Si columna Agenda exarescit, vigilia nocturna eam ex acervo replet chartis quae responsum tuum non requirunt. Mane unus acervus brevis manet: duae quaestiones et pauca temptanda, singula cum gradibus quos homo somnolentus sequi possit et imagine quae demonstrat id functionem habere. Percurris, bona accipis, reliqua remittis. Numerator signorum ostendit quantum omnia consumpserint, et No Token Mode hebdomadibus parcis est. Deinde ientaculum sumis, in quo agentes nondum iuvare possunt. Interea tabula per noctem pro te vigilat, tu autem semper decernis, et nihil sine tua voluntate perficitur.","Primum, quid AI-gile non sit. Non est incepta nova ad lucrum, non venditur, et nemo data tua colligit. Est tabula gratuita in computatro tuo currens, sine rationibus, sine indagatoribus, sine crustulis. Quid autem sit: unus locus ordinatus ad omnia incepta AI programmantia simul videnda, ubi turma agentium chartas conficit et tu decernis. Chartas cognatas coniungit, titulos perturbatos corrigit, et observat ut codex levis maneat. Circiter CXX linguis loquitur, a Batava et Flandrica ad piraticam et Klingonicam. Amici inter se scribere possunt, privatim et cryptatim. A Rich et magno numero agentium patientium aedificata est, plerumque se ipsa utentium. In alpha praevia clausa est, itaque quibusdam locis aspera est. Si iucunda videtur, bene roga et fortasse mature intrabis. Nihil celatur, nihil premitur."]}],"quips":{"1":"Unum verbum. Audax. Fortasse nimis audax.","3":"Tria verba. Iam sincerior quam pleraeque paginae productorum.","8":"Octo verba. Adhuc brevius quam conventus stantium.","21":"Longitudines, ut scias, puncta narrationis sunt. Scilicet.","55":"Quinquaginta quinque verba. Duae chartae confectae sunt dum legis.","144":"Haec est longissima. CCXXXIII non est. Agentes cubitum abierunt."}},"timeline":{"first-idea.name":"Prima idea","first-idea.line":"Primum colloquium, antequam ullus codex exstaret.","first-board.name":"Prima tabula","first-board.line":"Tabula quae suam ipsius constructionem sequitur: chartae, columnae, tractio, incepta.","team-roles.name":"Turma et munera","team-roles.line":"Profilia agentium, exemplaria turmarum, spatia et quis quid agat.","install.name":"Institutio et editiones","install.line":"Fasciculus zip quem amicus instituere possit, renovationes sponte, canales et regressus.","usage-saver.name":"Parsimonia usus","usage-saver.line":"Metire quanti cursus constent, codicem leve serva, terminum tuum conserva.","friends.name":"Amici et communicatio","friends.line":"Nuntii privati, relay confusum, invitationes, munera et incepta communia.","languages.name":"Linguae","languages.line":"Omnis textus scaenae in fasciculo linguae, Batava et Flandrica primis.","ai-tester.name":"Probator AI","ai-tester.line":"Probator omnem traditionem prior inspicit et ostendit quid viderit.","website.name":"Situs interretialis","website.line":"aigile.lol, pagina praenuntia et haec linea temporis.","streaming.name":"Colloquium et transmissio","streaming.line":"Discord, Twitch, OBS, modus transmissoris, GIF et emoji.","no-ai.name":"Editio sine AI","no-ai.line":"Tabula pro iis qui sine AI programmant, et tabulae publicae.","night-watch.name":"Vigilia nocturna","night-watch.line":"Vigil et Scrum Master turmas in opere tenent dum dormis.","p-more.name":"Cetera omnia","p-more.line":"Ideae minores quae vicem suam exspectant.","p-android.name":"Telephonum et Android","p-android.line":"Tabulam tuam e telephono attinge, deinde per applicationem Android propriam.","p-release.name":"Alpha et ultra","p-release.line":"Alpha clausa, situs vivus, deinde beta.","p-languages.name":"Plures linguae","p-languages.line":"Plus quam centum linguae, et modus immersionis discentibus.","p-engines.name":"Plura machinamenta AI","p-engines.line":"Claude, Codex vel Gemini pro quoque agente elige.","p-pro.name":"Usus professionalis","p-pro.line":"Tesserae periculi, portae coniunctionis, chartae incidentium et cancelli tutelae.","p-self.name":"Cura tui","p-self.line":"Modus fessus, admonitiones curae sui et 4:20.","p-servers.name":"Servientes et incrementum","p-servers.line":"Optiones servientium communes, munera et incrementi consilium.","p-livestream.name":"Additamenta transmissionis","p-livestream.line":"Colloquium Twitch, emoji propria et visus vivus publicus."}};
